import re

def parse(lines):
    skip = []
    sess = {}
    sess_l = []
    prog = []
    prog_l = []
    reps = []
    rep_l = []
    short = []
    short_l = []
    summ = {}
    summ_l = []
    warns = []
    warn_l = []
    wtests = []
    wdone = False
    section = ''
    rec = None
    sub = None
    for i, raw in enumerate(lines):
        s = raw.rstrip()
        if not s.strip():
            continue
        m = re.match(r'^=+ (.+?) =+$', s)
        if m:
            t = m.group(1)
            dm = re.search(r'\bin ([\d.]+s)\b', t)
            if dm:
                for n, w in re.findall(r'(\d+) (\w+)', t):
                    summ[w] = int(n)
                summ['duration'] = dm.group(1)
                summ_l.append(i)
            else:
                skip.append(i)
            section = t.lower()
            rec = None
            sub = None
            wtests = []
            wdone = False
            continue
        if re.match(r'^(?:_ )+_?$', s):
            if rec is not None:
                rep_l.append(i)
                rec['source'].append(s)
            else:
                skip.append(i)
            continue
        m = re.match(r'^_+ (.+?) _+$', s)
        if m and 'short test summary' not in section:
            rec = {'section': section, 'test': m.group(1), 'location': '', 'error_type': '', 'error': [], 'source': [], 'stdout': [], 'stderr': [], 'log': []}
            reps.append(rec)
            rep_l.append(i)
            sub = None
            continue
        m = re.match(r'^-+ (.+?) -+$', s)
        if m and rec is not None:
            sub = m.group(1).lower()
            rep_l.append(i)
            continue
        if section == 'warnings summary':
            if s.startswith('-- Docs:'):
                skip.append(i)
                continue
            m = re.match(r'^\s+(\S+?:\d+): (\w+): (.*)$', s)
            if m:
                warns.append({'tests': ' '.join(wtests), 'location': m.group(1), 'category': m.group(2), 'message': m.group(3), 'source': []})
                warn_l.append(i)
                wdone = True
                continue
            if not s[0].isspace():
                if wdone:
                    wtests = []
                    wdone = False
                wtests.append(s.strip())
                warn_l.append(i)
                continue
            if warns:
                warns[-1]['source'].append(s.strip())
                warn_l.append(i)
            else:
                skip.append(i)
            continue
        if section == 'test session starts' or section == '':
            m = re.match(r'^platform (\S+) -- (.*)$', s)
            if m:
                sess['platform'] = m.group(1)
                for item in m.group(2).split(', '):
                    km = re.match(r'(\S+?)[ -](\S+)$', item.strip())
                    if km:
                        sess[km.group(1)] = km.group(2)
                sess_l.append(i)
                continue
            m = re.match(r'^collected (\d+) items?(.*)$', s)
            if m:
                sess['collected'] = int(m.group(1))
                sess_l.append(i)
                continue
            m = re.match(r'^(\S+) ([.FEsxXp]+)\s*\[\s*(\d+%)\]$', s)
            if m:
                prog.append({'file': m.group(1), 'outcomes': m.group(2), 'progress': m.group(3)})
                prog_l.append(i)
                continue
            m = re.match(r'^(\w[\w ]*?): (.*)$', s)
            if m:
                sess[m.group(1)] = m.group(2)
                sess_l.append(i)
                continue
            continue
        if 'short test summary' in section:
            m = re.match(r'^(PASSED|FAILED|ERROR|SKIPPED|XFAIL|XPASS)\s+(?:\[(\d+)\]\s+)?(\S+?)(?::\s+| - |$)(.*)$', s)
            if m:
                short.append({'outcome': m.group(1), 'test': m.group(3), 'count': m.group(2) or '', 'reason': m.group(4)})
                short_l.append(i)
            continue
        if rec is not None:
            rep_l.append(i)
            if sub is None:
                m = re.match(r'^E\s+(.*)$', s)
                if m:
                    rec['error'].append(m.group(1))
                    continue
                m = re.match(r'^(\S+:\d+): (\w+)$', s)
                if m:
                    rec['location'] = m.group(1)
                    rec['error_type'] = m.group(2)
                    continue
                rec['source'].append(s)
            elif 'stderr' in sub:
                rec['stderr'].append(s)
            elif 'log' in sub:
                rec['log'].append(s)
            else:
                rec['stdout'].append(s)
            continue
        skip.append(i)
    for r in reps:
        for k in ('error', 'source', 'stdout', 'stderr', 'log'):
            r[k] = '\n'.join(r[k])
    for w in warns:
        w['source'] = '\n'.join(w['source'])
    blocks = []
    if sess:
        blocks.append({'name': 'session', 'kind': 'kv', 'lines': sess_l, 'records': [sess]})
    if prog:
        blocks.append({'name': 'progress', 'kind': 'table', 'lines': prog_l, 'records': prog})
    if reps:
        blocks.append({'name': 'reports', 'kind': 'table', 'lines': rep_l, 'records': reps})
    if warns:
        blocks.append({'name': 'warnings', 'kind': 'table', 'lines': warn_l, 'records': warns})
    if short:
        blocks.append({'name': 'short_test_summary', 'kind': 'table', 'lines': short_l, 'records': short})
    if summ:
        blocks.append({'name': 'summary', 'kind': 'kv', 'lines': summ_l, 'records': [summ]})
    return {'blocks': blocks, 'skip': skip}
